; Leever: X velocity toward Link (0 right, 1 left), 1 px/frame.
LeeverSpeeds:
    .byte   $10, $F0                                                        ; $990E

; ---------------------------------------------------------------------------
; Leever_Ai
;
; Leever (East Hyrule $16, a sand creature), by enemyAiState bits 1-0:
;
; 0. Hidden: when its timer runs out, it moves to a random X on the screen
;    (scrollX + rng+1,x) at its depth, facing Link with 1 pixel per frame
;    his way (LeeverSpeeds), and waits 80 frames.
; 1. Rising: during the last 24 of them it rises 1 pixel every other
;    frame, 12 pixels; then it moves on for 48-127 frames.
; 2. Moving: 1 pixel per frame, straight on; then it sinks.
; 3. Sinking: 1 pixel every other frame for 32 frames, 16 pixels; then it
;    stays hidden for 48-127 frames.
;
; It is drawn behind the background (Leever_Draw), so it shows only
; where the background is empty: above the sand.  It ignores walls and
; is tested for hits even while hidden.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Leever_Ai:
    jsr     Enemy_SkipAiIfStunned   ; $9910  no AI while stunned
    jsr     Enemy_UpdateCommon      ; $9913  draw, hit tests (no background)
    jsr     Enemy_HurtLinkOnContact ; $9916
    lda     enemyAiState,x          ; $9919
    and     #$03                    ; $991B
    jsr     JumpTable               ; $991D
; (inline jump table)
    .word   @hidden                 ; $9920
    .word   @rising                 ; $9922
    .word   @moving                 ; $9924
    .word   @sinking                ; $9926

@hidden:
    lda     timerFast+TIMER_ENEMY,x ; $9928  time to come up?
    bne     @done                   ; $992B
    lda     #$50                    ; $992D  80 frames to rise
    sta     timerFast+TIMER_ENEMY,x ; $992F
    lda     rng+1,x                 ; $9932  a random X on the screen
    adc     scrollX                 ; $9935
    sta     objX+1,x                ; $9938
    lda     scrollXHi               ; $993A
    adc     #$00                    ; $993D
    sta     objXHi+1,x              ; $993F
    jsr     Enemy_FaceLink          ; $9941  facing Link,
    lda     LeeverSpeeds,y          ; $9944  1 px/frame his way
    sta     objXVelocity+1,x        ; $9947
    lda     objState+1,x            ; $9949  at its depth
    sta     objY+1,x                ; $994B
    inc     enemyAiState,x          ; $994D  rising

@done:
    rts                             ; $994F

@rising:
    lda     timerFast+TIMER_ENEMY,x ; $9950
    beq     @nextPhase              ; $9953  done: move
    cmp     #$1A                    ; $9955  in the last 24 frames,
    bcs     @done2                  ; $9957
    and     #$01                    ; $9959  every other frame,
    bne     @done2                  ; $995B
    dec     objY+1,x                ; $995D  1 pixel up

@done2:
    rts                             ; $995F

@nextPhase:
    inc     enemyAiState,x          ; $9960  rising -> moving, sinking -> hidden
    lda     rng+1,x                 ; $9962  for 48-127 frames
    lsr     a                       ; $9965
    ora     #$30                    ; $9966
    sta     timerFast+TIMER_ENEMY,x ; $9968
    rts                             ; $996B

@moving:
    jsr     Enemy_MoveX             ; $996C
    lda     timerFast+TIMER_ENEMY,x ; $996F
    bne     @done3                  ; $9972
    inc     enemyAiState,x          ; $9974  then sink,
    lda     #$20                    ; $9976  for 32 frames
    sta     timerFast+TIMER_ENEMY,x ; $9978

@done3:
    rts                             ; $997B

@sinking:
    lda     timerFast+TIMER_ENEMY,x ; $997C
    beq     @nextPhase              ; $997F  done: hide
    lsr     a                       ; $9981  every other frame,
    bcc     Leever_Ai_Done          ; $9982
; Boon: X velocity by its direction 2, 3: read from here + 2, + 3,
; BoonYSpeeds: $20, $E0.
BoonXSpeeds := * + 1
    inc     objY+1,x                ; $9984  1 pixel down

Leever_Ai_Done:
    rts                             ; $9986
; (unreferenced: $9987-$9A10, 138 bytes)

; Boon: Y velocity by direction (0 down, 1 up); X velocity for 2, 3
; (BoonXSpeeds).
BoonYSpeeds:
    .byte   $20, $E0                                                        ; $9987
; (disassembled with tools/disasm.py; not executed in the test movies)

; ---------------------------------------------------------------------------
; Boon_Ai
;
; Boon (East Hyrule $17, a flying insect).  Whenever it isn't on screen
; (enemyAiState 0) it comes back at Y $30 at a random X on the screen.
; It flies 2 pixels per frame in one of four directions (objState+1: 0
; down, 1 up, 2 right, 3 left; BoonMoves), a new random one every 8-23
; frames (timerFast+TIMER_ENEMY), with no limits but the screen.  Every
; 32 frames (frameCounter), while above Y $70, it drops a rock
; (Enemy_DropRock_Bank2), even while stunned.  It faces Link.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boon_Ai:
    lda     objY+1,x                ; $9989  above Y $70,
    cmp     #$70                    ; $998B
    bcs     @setFacing              ; $998D
    lda     frameCounter            ; $998F  every 32 frames:
    and     #$1F                    ; $9991
    bne     @setFacing              ; $9993
    jsr     Enemy_DropRock_Bank2    ; $9995  drop a rock

@setFacing:
    ldy     #$01                    ; $9998  face its X velocity
    lda     objXVelocity+1,x        ; $999A  (replaced below by
    bpl     @storeFacing            ; $999C  Enemy_FaceLink unless stunned)
    iny                             ; $999E

@storeFacing:
    sty     objFacing+1,x           ; $999F
    jsr     Enemy_SkipAiIfStunned   ; $99A1  no AI while stunned
    jsr     Enemy_UpdateCommon      ; $99A4  draw, hit tests (no background)
    jsr     Enemy_HurtLinkOnContact ; $99A7
    jsr     Enemy_FaceLink          ; $99AA  face Link
    lda     enemyAiState,x          ; $99AD
    bne     @flying                 ; $99AF
    ; Come (back) on screen: at Y $30, a random X.
    sta     objState+1,x            ; $99B1  direction 0
    lda     #$30                    ; $99B3
    sta     objY+1,x                ; $99B5
    lda     #$01                    ; $99B7
    sta     objYHi+1,x              ; $99B9
    lda     rng+1,x                 ; $99BB  X = screen's left edge
    adc     scrollX                 ; $99BE  + 0-255
    sta     objX+1,x                ; $99C1
    lda     scrollXHi               ; $99C3
    adc     #$00                    ; $99C6
    sta     objXHi+1,x              ; $99C8
    lda     #$20                    ; $99CA  first turn in 32 frames
    sta     timerFast+3,x           ; $99CC
    inc     enemyAiState,x          ; $99CF  flying
    rts                             ; $99D1

@flying:
    lda     drawOffscreen+1         ; $99D2  off screen (either side, or
    and     #$CC                    ; $99D4  above or below)?
    beq     @checkTurn              ; $99D6
    dec     enemyAiState,x          ; $99D8  come back next frame

@checkTurn:
    lda     timerFast+3,x           ; $99DA  time to turn?
    bne     @move                   ; $99DD
    lda     rng+1,x                 ; $99DF  next turn in 8-23 frames,
    pha                             ; $99E2
    and     #$0F                    ; $99E3
    ora     #$08                    ; $99E5
    sta     timerFast+3,x           ; $99E7
    pla                             ; $99EA
    and     #$03                    ; $99EB  a random direction
    sta     objState+1,x            ; $99ED

@move:
    lda     objState+1,x            ; $99EF
    jsr     JumpTable               ; $99F1  (BoonMoves)
; (end of disassembled code)


; Boon_Ai's jump table, by objState (its direction of travel).
BoonMoves:
    .word   Boon_MoveY, Boon_MoveY, Boon_MoveX, Boon_MoveX ; $99F4
; (disassembled with tools/disasm.py; not executed in the test movies)

; Boon: fly down (direction 0) or up (1) at 2 px/frame.
Boon_MoveY:
    ldy     objState+1,x            ; $99FC  direction 0 or 1
    lda     BoonYSpeeds,y           ; $99FE  $20 down, $E0 up
    sta     objYVelocity+1,x        ; $9A01
    jmp     Enemy_MoveY             ; $9A04

; Boon: fly right (direction 2) or left (3) at 2 px/frame.
Boon_MoveX:
    ldy     objState+1,x            ; $9A07  direction 2 or 3
    lda     BoonXSpeeds,y           ; $9A09  $20 right, $E0 left
    sta     objXVelocity+1,x        ; $9A0C
    jmp     Enemy_MoveX             ; $9A0E
; (end of disassembled code)


; ---------------------------------------------------------------------------
; Enemy_DropRock_Bank2
;
; Drop a rock (projectile type 8, Projectile_FallingRock_Bank2) from enemy
; x's position, with no speed, if a projectile slot is free.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_DropRock_Bank2:
    jsr     Enemy_FireProjectile    ; $9A11  from its position
    bcs     Enemy_DropRock_Done_Bank2 ; $9A14  no free slot
    lda     #$08                    ; $9A16  projectile type 8
    sta     a:objState+7,y          ; $9A18
    lda     #$00                    ; $9A1B  just dropped
    sta     objYVelocity+7,y        ; $9A1D
    sta     a:objXVelocity+7,y      ; $9A20

Enemy_DropRock_Done_Bank2:
    rts                             ; $9A23
    ; Enemy_Pace_Bank2's speeds, by facing (1, 2) from the rts: $F8, and
    ; $08 (the next table's first byte).
    .byte   $F8                                                             ; $9A24

; Basilisk: fireball X offset by facing (1, 2) while reared: +$0E, then
; -8 (with the next table's first byte).
BasiliskFireXOffsets:
    .byte   $08, $0E                                                        ; $9A25

; Basilisk: high byte of that offset, by facing (1: $00, 2: $FF).
BasiliskFireXHiOffsets:
    .byte   $F8, $00, $FF                                                   ; $9A27

; ---------------------------------------------------------------------------
; Basilisk_Ai
;
; Basilisk (East Hyrule $18, a crested lizard).  It crawls low on the
; 256-step pace of Enemy_Pace_Bank2 (back off, stand, advance, stand) and
; turns toward Link every 64 frames.  At frameCounter 0, every 256
; frames, it rears up and stands for 80 frames (timerFast+TIMER_ENEMY);
; its type's hitbox entry (sramEnemyHitbox+$18) is $80 while reared and
; $89 while crawling.  Every 64 frames, half the time, it breathes a
; fireball 10 frames later (objState+1 counting down): projectile type 6,
; 2 pixels per frame the way it faces, from Y + 16 while crawling, or
; from Y + 4 and further ahead (+14 facing right, -8 left) while reared.
; It walks off ledges.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Basilisk_Ai:
    lda     frameCounter            ; $9A2A  every 64 frames,
    and     #$3F                    ; $9A2C
    bne     @fall                   ; $9A2E
    lda     rng+1,x                 ; $9A30  half the time,
    lsr     a                       ; $9A33
    bcc     @fall                   ; $9A34
    lda     #$0A                    ; $9A36  breathe fire in 10 frames
    sta     objState+1,x            ; $9A38

@fall:
    jsr     Enemy_Fall_Bank2        ; $9A3A  probe, fall or land
    lda     #$80                    ; $9A3D  hitbox $80 reared,
    ldy     timerFast+TIMER_ENEMY,x ; $9A3F
    bne     @setHitbox              ; $9A42
    lda     #$89                    ; $9A44  $89 crawling

@setHitbox:
    sta     sramEnemyHitbox+24      ; $9A46  (the type's own entry)
    jsr     Enemy_UpdateCommon      ; $9A49  draw, hit tests
    jsr     Enemy_HurtLinkOnContact ; $9A4C
    jsr     Enemy_KnockBackOrWalk_Bank2 ; $9A4F  move by last frame's velocity
    lda     frameCounter            ; $9A52  every 64 frames
    and     #$3F                    ; $9A54
    bne     @pace                   ; $9A56
    jsr     Enemy_FaceLink          ; $9A58  turn toward Link

@pace:
    lda     #$00                    ; $9A5B  stand,
    sta     objXVelocity+1,x        ; $9A5D
    lda     timerFast+TIMER_ENEMY,x ; $9A5F  unless crawling:
    bne     @countdown              ; $9A62
    lda     frameCounter            ; $9A64  every 256 frames,
    bne     @walk                   ; $9A66
    lda     #$50                    ; $9A68  rear up for 80 frames
    sta     timerFast+TIMER_ENEMY,x ; $9A6A

@walk:
    jsr     Enemy_Pace_Bank2        ; $9A6D  next frame's velocity

@countdown:
    lda     objState+1,x            ; $9A70  breathing fire?
    beq     @done                   ; $9A72
    dec     objState+1,x            ; $9A74
    bne     @done                   ; $9A76  not yet
    jsr     Enemy_FireProjectile    ; $9A78  a fireball the way it faces
    bcs     @done                   ; $9A7B
    lda     #$06                    ; $9A7D  projectile type 6
    sta     a:objState+7,y          ; $9A7F
    lda     a:objY+7,y              ; $9A82  4 pixels lower
    adc     #$04                    ; $9A85
    sta     a:objY+7,y              ; $9A87
    lda     timerFast+TIMER_ENEMY,x ; $9A8A  reared?
    bne     @forward                ; $9A8D
    lda     a:objY+7,y              ; $9A8F  crawling: 12 more, Y + 16
    clc                             ; $9A92
    adc     #$0C                    ; $9A93
    sta     a:objY+7,y              ; $9A95
    rts                             ; $9A98

@forward:
    ldx     objFacing+7,y           ; $9A99  reared: from its raised head,
    lda     a:objX+7,y              ; $9A9B  +14 facing right, -8 left
    adc     BasiliskFireXOffsets,x  ; $9A9E
    sta     a:objX+7,y              ; $9AA1
    lda     a:objXHi+7,y            ; $9AA4
    adc     BasiliskFireXHiOffsets,x ; $9AA7
    sta     a:objXHi+7,y            ; $9AAA

@done:
    rts                             ; $9AAD

; ---------------------------------------------------------------------------
; Scorpion_Ai
;
; Scorpion (East Hyrule $19).  It walks on the 256-step pace of
; Enemy_Pace_Bank2 (back off, stand, advance, stand), turning toward Link
; every 64 frames, and walks off ledges.  Its guard 3 (enemyAiVar,
; Enemy_GetSpecialHitbox: its body, 24 pixels wide from 16 to 32 below
; its Y) turns aside Link's projectiles and low sword strokes; a high
; stroke passes over it.  On 1 frame in 64 at random it drops its guard
; for 32 frames (objState+1 counting down; its head changes,
; Scorpion_Draw), when it can be hit.  On 1 frame in 64 at random
; (rng+2,x) it raises its tail (timerFast+TIMER_ENEMY = 16) and 8 frames
; later fires projectile type 4 (a fireball, with a sound) the way it
; faces.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Scorpion_Ai:
    jsr     Enemy_Fall_Bank2        ; $9AAE  probe, fall or land
    lda     objState+1,x            ; $9AB1  guard down?
    bne     @guardDown              ; $9AB3
    jsr     Enemy_Draw              ; $9AB5  no: draw, and test guard 3
    lda     #$03                    ; $9AB8
    sta     enemyAiVar,x            ; $9ABA
    jsr     Enemy_CheckProjectileHitsSpecial ; $9ABD  (a clink returns from here)
    jmp     @update                 ; $9AC0

@guardDown:
    dec     objState+1,x            ; $9AC3  count the 32 frames

@update:
    jsr     Enemy_UpdateCommon      ; $9AC5  draw, hit tests
    jsr     Enemy_HurtLinkOnContact ; $9AC8
    jsr     Enemy_KnockBackOrWalk_Bank2 ; $9ACB  move by last frame's velocity
    lda     frameCounter            ; $9ACE  every 64 frames
    and     #$3F                    ; $9AD0
    bne     @maybeDropGuard         ; $9AD2
    jsr     Enemy_FaceLink          ; $9AD4  turn toward Link

@maybeDropGuard:
    lda     rng+1,x                 ; $9AD7  1 frame in 64 (bits 7-2
    eor     #$FF                    ; $9ADA  all set):
    and     #$FC                    ; $9ADC
    bne     @maybeAim               ; $9ADE
    lda     #$20                    ; $9AE0  guard down for 32 frames
    sta     objState+1,x            ; $9AE2

@maybeAim:
    lda     rng+2,x                 ; $9AE4  1 frame in 64:
    and     #$3F                    ; $9AE7
    bne     @pace                   ; $9AE9
    lda     #$10                    ; $9AEB  raise its tail for 16 frames
    sta     timerFast+TIMER_ENEMY,x ; $9AED

@pace:
    lda     #$00                    ; $9AF0
    sta     objXVelocity+1,x        ; $9AF2
    jsr     Enemy_Pace_Bank2        ; $9AF4  next frame's velocity
    lda     timerFast+TIMER_ENEMY,x ; $9AF7  8 frames into the aim:
    cmp     #$08                    ; $9AFA
    bne     @done                   ; $9AFC
    jsr     Enemy_FireProjectile    ; $9AFE  fire the way it faces
    bcs     @done                   ; $9B01
    lda     #$04                    ; $9B03  projectile type 4
    sta     a:objState+7,y          ; $9B05

@done:
    rts                             ; $9B08

; ---------------------------------------------------------------------------
; Enemy_Pace_Bank2
;
; Set enemy x's X velocity for its pace, by enemyAiState (counted up
; here) bits 7-6: 0, 1/2 pixel per frame away from its facing; 1 and 3,
; none (the caller has set 0); 2, about 1 pixel per frame toward it
; ($0F / $EF).  The speeds are the bytes after Enemy_DropRock_Done_Bank2,
; by facing: $F8 (right), $08 (left).  Over 256 calls it backs off 32
; pixels and advances 60.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_Pace_Bank2:
    inc     enemyAiState,x          ; $9B09  count
    ldy     objFacing+1,x           ; $9B0B
    lda     enemyAiState,x          ; $9B0D
    and     #$C0                    ; $9B0F  quarter 0:
    bne     @otherQuarters          ; $9B11
    lda     Enemy_DropRock_Done_Bank2,y ; $9B13  1/2 px/frame backward
    bne     @setSpeed               ; $9B16  (always)

@otherQuarters:
    asl     a                       ; $9B18  quarters 1, 3: stand
    bne     Enemy_Pace_Done_Bank2   ; $9B19
    lda     Enemy_DropRock_Done_Bank2,y ; $9B1B  quarter 2: about 1 px/frame
    asl     a                       ; $9B1E  forward (-2v - 1)
    eor     #$FF                    ; $9B1F

@setSpeed:
    sta     objXVelocity+1,x        ; $9B21

Enemy_Pace_Done_Bank2:
    rts                             ; $9B23

; ---------------------------------------------------------------------------
; Enemy_KnockBackOrWalk_Bank2
;
; While knocked back (enemyKnockBack), move by the knockback, which shrinks
; by 1/16 pixel per frame toward 0 (with a background probe); then, or
; otherwise (Enemy_Walk_Bank2), move by the X velocity unless at a wall.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_KnockBackOrWalk_Bank2:
    lda     enemyKnockBack,x        ; $9B24
    beq     Enemy_Walk_Bank2        ; $9B27  not knocked back
; (code below not executed in the test movies)
    dec     enemyKnockBack,x        ; $9B29  shrink toward 0
    bpl     @knockedBack            ; $9B2C
    inc     enemyKnockBack,x        ; $9B2E
    inc     enemyKnockBack,x        ; $9B31

@knockedBack:
    sta     objXVelocity+1,x        ; $9B34  move by it
    jsr     Enemy_UpdateBgCollision ; $9B36
; (end of code not executed in the test movies)

Enemy_Walk_Bank2:
    lda     objCollision+1,x        ; $9B39  wall ahead?
    and     #$03                    ; $9B3B
    bne     Enemy_Pace_Done_Bank2   ; $9B3D  yes: stay
    jmp     Enemy_MoveX             ; $9B3F

; ---------------------------------------------------------------------------
; Enemy_Fall_Bank2
;
; Probe enemy x's background (Enemy_UpdateBgCollision); land it on a floor
; it is coming down on (Enemy_Land), else fall (Enemy_MoveYAndFall,
; gravity 2/16 pixel per frame per frame).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_Fall_Bank2:
    jsr     Enemy_UpdateBgCollision ; $9B42
    lda     objYVelocity+1,x        ; $9B45  rising: keep moving
    bmi     @fall                   ; $9B48
    lda     objCollision+1,x        ; $9B4A
    and     #$04                    ; $9B4C  on a floor?
    beq     @fall                   ; $9B4E
    jmp     Enemy_Land              ; $9B50  yes: land

@fall:
    jmp     Enemy_MoveYAndFall      ; $9B53

; ---------------------------------------------------------------------------
; OrangeLizalfos_Ai
;
; Orange Lizalfos ($1B): as Lizalfos_Guard, with its own attack.  After
; the 24-frame wind-up (pose 1 low or 4 high, Lizalfos_ChooseGuard) it
; thrusts (pose 2 or 5) for 12 frames, its weapon tested against Link's
; shield and body every frame (Weapon_CheckLink), then holds (3 or
; 6) for 12 frames.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeLizalfos_Ai:
    jsr     Enemy_Draw              ; $9B56
    lda     objState+1,x            ; $9B59  attacking?
    beq     Lizalfos_GuardFar       ; $9B5B  no
    cmp     #$02                    ; $9B5D  thrusting (pose 2 or 5)?
    beq     @thrust                 ; $9B5F
    cmp     #$05                    ; $9B61
    bne     @checkTimer             ; $9B63

@thrust:
    jsr     Weapon_CheckLink        ; $9B65  the weapon against Link

@checkTimer:
    lda     timerFast+TIMER_ENEMY,x ; $9B68  pose over?
    bne     Lizalfos_GuardFar       ; $9B6B
LizalfosAttackPeriods := * + 1
    inc     objState+1,x            ; $9B6D  next pose
    lda     objState+1,x            ; $9B6F
    cmp     #$04                    ; $9B71  low attack over?

LizalfosRanges:
    beq     Lizalfos_ResetPose      ; $9B73
    cmp     #$07                    ; $9B75  high attack over?
    bcs     Lizalfos_ResetPose      ; $9B77
    lda     #$0C                    ; $9B79  next pose in 12 frames
    sta     timerFast+TIMER_ENEMY,x ; $9B7B

Lizalfos_GuardFar:
    jmp     Lizalfos_GuardFar2      ; $9B7E

Lizalfos_ResetPose:
    lda     #$00                    ; $9B81  attack over
    sta     objState+1,x            ; $9B83

Lizalfos_GuardFar2:
    jmp     Lizalfos_Guard          ; $9B85
    ; LizalfosAttackPeriods for types $1A-$1C (indexed from $9B6E).
    .byte   $3F, $1F, $3F                                                   ; $9B88

; Lizalfos: X velocity toward Link (0 right, 1 left), doubled; the next
; bytes are LizalfosRanges for types $1A-$1C ($18, $18, $40).
LizalfosSpeeds:
    .byte   $08, $F8, $18, $18, $40                                         ; $9B8B

; ---------------------------------------------------------------------------
; Lizalfos_Ai
;
; Lizalfos ($1A red, $1C blue): plays out its attack (Lizalfos_Attack),
; then Lizalfos_Guard, shared with the orange Lizalfos.  Like a fighter
; (Fighter_Move) it keeps a distance r from Link (LizalfosRanges: $18,
; $18, $40 for red, orange, blue), walking toward him at 1 pixel per
; frame and attacking as it comes within $50 pixels.  Near, it holds,
; swaying or keeping pace with him, and attacks every 64 frames (32 for
; the orange; LizalfosAttackPeriods).  (A quarter of the time it sets the
; count to $C0, as the fighters set $E0 for a quicker attack; but $C0 is
; a multiple of either period, so nothing changes.)
;
; It guards with its shield (guard 0 low or 1 high, enemyAiVar;
; Enemy_CheckProjectileHitsSpecial): when Link presses B, 3 times in 4,
; at the height of his stroke (high standing, low crouching); and while
; he jumps, high if he is more than 10 pixels above it, else low.  So
; strokes at one height clink off, and only a change of height, the
; quarter of the time it doesn't follow, gets through.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Lizalfos_Ai:
    jsr     Enemy_Draw              ; $9B90
    jsr     Lizalfos_Attack         ; $9B93

Lizalfos_Guard:
    ldy     enemyType,x             ; $9B96
    lda     LizalfosRanges,y        ; $9B98  r
    sta     ram_05E4                ; $9B9B
    asl     a                       ; $9B9E
    sta     ram_05E5                ; $9B9F  2r
    lda     joypadPressed           ; $9BA2  B just pressed,
    and     #$40                    ; $9BA4
    beq     @testGuard              ; $9BA6
    lda     rng+1,x                 ; $9BA8  3 times in 4:
    and     #$03                    ; $9BAB
    beq     @testGuard              ; $9BAD
    lda     linkStanding            ; $9BAF  guard at his stroke's height
    sta     enemyAiVar,x            ; $9BB1  (1 high, 0 low)

@testGuard:
    jsr     Enemy_CheckProjectileHitsSpecial ; $9BB4  (a clink returns from here)
    jsr     Enemy_UpdateBgCollision ; $9BB7
    ; Enemy_UpdateCommon, without drawing it again.
    ldy     #$01                    ; $9BBA
    inx                             ; $9BBC
    jsr     Obj_ComputeScreenPos    ; $9BBD
    ldx     currentObject           ; $9BC0
    lda     objYHi+1,x              ; $9BC2  fallen below the screen?
    cmp     #$02                    ; $9BC4
    bcc     @onScreen               ; $9BC6
; (code below not executed in the test movies)
    jmp     Enemy_Despawn           ; $9BC8
; (end of code not executed in the test movies)

@onScreen:
    lda     drawOffscreen+1         ; $9BCB  off screen: no hit tests,
    and     #$FC                    ; $9BCD  despawn if far
    beq     @hitTests               ; $9BCF
    lda     objCollision+1,x        ; $9BD1
    and     #$0F                    ; $9BD3
    sta     objCollision+1,x        ; $9BD5
    jsr     Enemy_DespawnIfFar      ; $9BD7
    jmp     @move                   ; $9BDA

@hitTests:
    jsr     Enemy_CheckProjectileHits ; $9BDD
    jsr     Enemy_CheckSwordHit     ; $9BE0
    jsr     Enemy_CheckLinkContact  ; $9BE3

@move:
    jsr     Enemy_HurtLinkOnContact ; $9BE6
    jsr     Enemy_MoveYAndFall      ; $9BE9  fall
    lda     objCollision+1,x        ; $9BEC
    and     #$04                    ; $9BEE  on a floor?
    beq     @knockBack              ; $9BF0
    jsr     Enemy_Land              ; $9BF2

@knockBack:
    jsr     Lizalfos_KnockBack      ; $9BF5  move (or be knocked back and stop)
    jsr     Enemy_FaceLink          ; $9BF8  temp15 = dx, y = 0 if right
    lda     temp15                  ; $9BFB
    clc                             ; $9BFD
    adc     ram_05E4                ; $9BFE  -r <= dx < r?
    cmp     ram_05E5                ; $9C01
    bcc     Lizalfos_ChooseGuard    ; $9C04  near: hold and attack
    lda     temp15                  ; $9C06
    clc                             ; $9C08
    adc     #$50                    ; $9C09  within $50?
    cmp     #$A0                    ; $9C0B
    bcs     @walk                   ; $9C0D
    jsr     Lizalfos_ChooseGuard    ; $9C0F  attack as it comes
    jsr     Enemy_FaceLink          ; $9C12  (y again)

@walk:
    lda     LizalfosSpeeds,y        ; $9C15  1 px/frame toward Link
    asl     a                       ; $9C18
    sta     objXVelocity+1,x        ; $9C19
    rts                             ; $9C1B

; Near Link: guard against his jump, attack on time, else hold (as
; Fighter_Stop).
Lizalfos_ChooseGuard:
    lda     objState+1,x            ; $9C1C  attacking?
    bne     @hold                   ; $9C1E  yes
    lda     linkJumpState           ; $9C20  Link in the air?
    beq     @countFrame             ; $9C23
    ldy     #$01                    ; $9C25  high guard if his Y + 10 is
    lda     objY                    ; $9C27  above its Y,
    adc     #$0A                    ; $9C29
    cmp     objY+1,x                ; $9C2B
    bcc     @setGuard               ; $9C2D
    dey                             ; $9C2F  else low

@setGuard:
    tya                             ; $9C30
    sta     enemyAiVar,x            ; $9C31

@countFrame:
    inc     enemyAiState,x          ; $9C34  attack every period
    ldy     enemyType,x             ; $9C36
    lda     LizalfosAttackPeriods,y ; $9C38
    and     enemyAiState,x          ; $9C3B
    bne     @hold                   ; $9C3D  not yet
    lda     rng+1,x                 ; $9C3F  a quarter of the time,
    and     #$03                    ; $9C42
    bne     @startAttack            ; $9C44
    lda     #$C0                    ; $9C46  count = $C0 (no effect: a
    sta     enemyAiState,x          ; $9C48  multiple of the period)

@startAttack:
    ldy     #$01                    ; $9C4A  pose 1: low,
    lda     enemyType,x             ; $9C4C
    cmp     #$1B                    ; $9C4E  except the orange Lizalfos:
    bne     @setPose                ; $9C50
    lda     rng+1,x                 ; $9C52  half the time high,
    lsr     a                       ; $9C55
    bcs     @high                   ; $9C56
    lda     linkStanding            ; $9C58  half the time away from his
    bne     @setPose                ; $9C5A  shield (low if he stands)

@high:
    iny                             ; $9C5C  pose 4: high
    iny                             ; $9C5D
    iny                             ; $9C5E

@setPose:
    sty     objState+1,x            ; $9C5F
    lda     #$18                    ; $9C61  wind up for 24 frames
    sta     timerFast+TIMER_ENEMY,x ; $9C63

@hold:
    lda     #$00                    ; $9C66  stop
    sta     objXVelocity+1,x        ; $9C68
    lda     objCollision            ; $9C6A  Link against a wall: stay
    and     #$03                    ; $9C6C
    bne     @done                   ; $9C6E
    lda     linkDirHeld             ; $9C70  Link walking: keep pace,
    beq     @sway                   ; $9C73
    lda     objXVelocity            ; $9C75
    bne     @setSpeed               ; $9C77

@sway:
    ldy     #$04                    ; $9C79  else sway, every 64 frames
    lda     frameCounter            ; $9C7B
    and     #$40                    ; $9C7D
    bne     @swayDir                ; $9C7F
    ldy     #$FC                    ; $9C81

@swayDir:
    tya                             ; $9C83

@setSpeed:
    sta     objXVelocity+1,x        ; $9C84  halved, keeping the sign
    asl     a                       ; $9C86
    ror     objXVelocity+1,x        ; $9C87

@done:
    rts                             ; $9C89
; (unreferenced: $9C8A-$9CB9, 48 bytes)
    .byte   $B5, $AF, $4A, $B0, $14, $BD, $04, $05, $D0, $07, $F6, $AF, $A9, $40, $9D, $04; $9C8A
    .byte   $05, $B4, $60, $B9, $8A, $9B, $95, $71, $60, $A9, $00, $95, $71, $BD, $04, $05; $9C9A
    .byte   $D0, $0D, $F6, $AF, $A9, $80, $9D, $04, $05, $B5, $60, $49, $03, $95, $60; $9CAA

; Blue Lizalfos' thrown weapon: X offset by facing (1: +$10, 2: -8).
LizalfosShotXOffsets:
    .byte   $60                                                             ; $9CB9
    .byte   $10                                                             ; $9CBA

LizalfosShotXHiOffsets:
    .byte   $F8, $00, $FF                                                   ; $9CBB

; ---------------------------------------------------------------------------
; Lizalfos_Attack
;
; Play out a red or blue Lizalfos' attack.  After the 24-frame wind-up
; (pose 1), every 5 frames the pose advances: pose 2 is the thrust, its
; weapon drawn at once and tested against Link like a projectile
; (Weapon_CheckLinkReflect); the attack ends at pose 4.  The blue
; Lizalfos throws its weapon at pose 2 instead and ends there: projectile
; type 7, 2 pixels per frame straight ahead, from 16 pixels right (facing
; right) or 8 left of it (LizalfosShotXOffsets).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Lizalfos_Attack:
    lda     objState+1,x            ; $9CBE  attacking?
    beq     @done                   ; $9CC0
    lda     timerFast+TIMER_ENEMY,x ; $9CC2  pose over?
    bne     @done                   ; $9CC5
    inc     objState+1,x            ; $9CC7  next pose
    lda     objState+1,x            ; $9CC9
    cmp     #$04                    ; $9CCB  over?
    beq     @end                    ; $9CCD
    cmp     #$02                    ; $9CCF  the thrust?
    bne     @nextIn5                ; $9CD1
    jsr     Enemy_Draw              ; $9CD3  draw the weapon now,
    jsr     Weapon_CheckLinkReflect ; $9CD6  and test it
    lda     enemyType,x             ; $9CD9
    cmp     #$1C                    ; $9CDB  the blue Lizalfos
    bne     @nextIn5                ; $9CDD
    jsr     Enemy_FireProjectile    ; $9CDF  throws it:
    bcs     @nextIn5                ; $9CE2
    ldx     objFacing+7,y           ; $9CE4  from ahead of it
    lda     a:objX+7,y              ; $9CE6
    adc     LizalfosShotXOffsets,x  ; $9CE9
    sta     a:objX+7,y              ; $9CEC
    lda     a:objXHi+7,y            ; $9CEF
    adc     LizalfosShotXHiOffsets,x ; $9CF2
    sta     a:objXHi+7,y            ; $9CF5
    lda     #$07                    ; $9CF8  projectile type 7
    sta     a:objState+7,y          ; $9CFA
    ldx     currentObject           ; $9CFD
    jmp     @end                    ; $9CFF  and the attack is over

@nextIn5:
    lda     #$05                    ; $9D02  next pose in 5 frames
    sta     timerFast+TIMER_ENEMY,x ; $9D04

@done:
    rts                             ; $9D07

@end:
    lda     #$00                    ; $9D08  attack over
    sta     objState+1,x            ; $9D0A
    rts                             ; $9D0C
; (unreferenced: $9D0D-$9D12, 6 bytes)
    .byte   $00, $00, $00, $00, $00, $00                                    ; $9D0D

; ---------------------------------------------------------------------------
; Lizalfos_KnockBack
;
; Move a Lizalfos by its X velocity unless at a wall (Enemy_Walk_Bank2);
; while it is knocked back, move it by enemyKnockBack instead, which
; shrinks by 1/16 pixel per frame toward 0, and return from
; Lizalfos_Guard too, skipping the rest of the AI.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Lizalfos_KnockBack:
    lda     enemyKnockBack,x        ; $9D13
    beq     @walk                   ; $9D16  not knocked back
    dec     enemyKnockBack,x        ; $9D18  shrink toward 0
    bpl     @knockedBack            ; $9D1B
    inc     enemyKnockBack,x        ; $9D1D
    inc     enemyKnockBack,x        ; $9D20

@knockedBack:
    sta     objXVelocity+1,x        ; $9D23  move by it,
    pla                             ; $9D25  and return from Lizalfos_Guard
    pla                             ; $9D26

@walk:
; RockThrower_Draw: arm X offsets by throw phase (+2 facing right), from
; the jmp's high byte: $08, $FC, $FC, then $08 (RockThrowerRockYOffsets).
RockThrowerDrawTiles := * + 2
    jmp     Enemy_Walk_Bank2        ; $9D27
    .byte   $08, $FC, $FC                                                   ; $9D2A

; RockThrower_Draw: arm Y from its Y by throw step (1: -16, 2: -13).
RockThrowerRockYOffsets:
    .byte   $08, $F0                                                        ; $9D2D

; RockThrower_Draw: the rock's X from the arm's, by facing (1: -6, 2: +6).
RockThrowerRockXOffsets:
    .byte   $F3, $FA, $06                                                   ; $9D2F

; ---------------------------------------------------------------------------
; RockThrower_Draw
;
; Draw a rock thrower behind the background (priority bit), so that the
; fence hides it: a pair of sprites from sramEnemyTiles entry $2C.  While
; it throws (objState+1 = 1, 2) it adds its arm, tile $23, at Y +
; RockThrowerRockYOffsets (wind-up: 16 above; follow-through: 13
; above), mirrored and flipped in the follow-through, shifted by
; RockThrowerDrawTiles (doubled in the wind-up's last 7 frames and in
; the follow-through);
; in the wind-up also the rock in its hand, tile $AE, beside the arm.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
RockThrower_Draw:
    lda     temp3                   ; $9D32  behind the background
    ora     #$20                    ; $9D34
    sta     temp3                   ; $9D36
    ldx     #$2C                    ; $9D38  entry $2C
    jsr     Sprite_DrawEnemyPairKeepX ; $9D3A
    lda     drawOffscreen+1         ; $9D3D  partly off screen: no arm
    bne     @done                   ; $9D3F
    lda     objState+1,x            ; $9D41  throwing?
    beq     @done                   ; $9D43
    tax                             ; $9D45  x = throw step (1, 2)
    lda     #$23                    ; $9D46  the arm
    sta     oamBuffer+1,y           ; $9D48
    lda     temp0                   ; $9D4B  Y by step
    adc     RockThrowerRockYOffsets,x ; $9D4D
    sta     oamBuffer,y             ; $9D50
    lda     oamBuffer - 6,y         ; $9D53  the body's attributes,
    cpx     #$02                    ; $9D56
    bne     @setAttr                ; $9D58
    eor     #$C0                    ; $9D5A  flipped both ways in step 2

@setAttr:
    sta     oamBuffer+2,y           ; $9D5C  (arm and rock)
    sta     oamBuffer+6,y           ; $9D5F
    lda     temp2                   ; $9D62  facing right: the second pair
    lsr     a                       ; $9D64  of offsets
    bne     @armX                   ; $9D65
    inx                             ; $9D67
    inx                             ; $9D68

@armX:
    stx     temp14                  ; $9D69
    sty     temp15                  ; $9D6B
    lda     RockThrowerDrawTiles,x  ; $9D6D  arm X offset
    cpx     #$01                    ; $9D70  wind-up (either facing):
    beq     @windUp                 ; $9D72
    cpx     #$03                    ; $9D74
    bne     @double                 ; $9D76

@windUp:
    ldx     currentObject           ; $9D78  its first 10 frames:
    ldy     enemyAiVar,x            ; $9D7A  as is
    cpy     #$07                    ; $9D7D
    bcs     @addX                   ; $9D7F

@double:
    asl     a                       ; $9D81  else doubled

@addX:
    clc                             ; $9D82
    adc     temp1                   ; $9D83
    ldy     temp15                  ; $9D85
    sta     oamBuffer+3,y           ; $9D87
    lda     temp14                  ; $9D8A  wind-up: the rock in hand
    and     #$01                    ; $9D8C
    beq     @done                   ; $9D8E
    ldx     temp2                   ; $9D90  beside the arm
    lda     oamBuffer+3,y           ; $9D92
    clc                             ; $9D95
    adc     RockThrowerRockXOffsets,x ; $9D96
    sta     oamBuffer+7,y           ; $9D99
    lda     #$AE                    ; $9D9C  tile $AE
    sta     oamBuffer+5,y           ; $9D9E
    lda     oamBuffer,y             ; $9DA1  3 above the arm
    sbc     #$03                    ; $9DA4
    sta     oamBuffer+4,y           ; $9DA6

@done:
    ldx     currentObject           ; $9DA9
    rts                             ; $9DAB

; ---------------------------------------------------------------------------
; Tektite_Draw
;
; Draw a Tektite: two pairs of sprites facing its objFacing, from
; sramEnemyTiles entry $00, or $04 while its hitbox is the tall $89 (legs
; stretched); the top pair lowered by its cycle step's distance from 0
; (enemyAiState, 0-15 pixels), so that it crouches and stretches.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Tektite_Draw:
    ldx     #$00                    ; $9DAC  entry $00,
    lda     sramEnemyHitbox+20      ; $9DAE
    cmp     #$89                    ; $9DB1
    bne     @draw                   ; $9DB3
    ldx     #$04                    ; $9DB5  or $04 stretched

@draw:
    jsr     Sprite_DrawEnemyPair    ; $9DB7  top pair
    jsr     Sprite_DrawEnemyPairKeepX ; $9DBA  bottom pair
    lda     enemyAiState,x          ; $9DBD  |step| (one less for negative
    bpl     @lower                  ; $9DBF  steps)
    eor     #$FF                    ; $9DC1

@lower:
    sta     temp0                   ; $9DC3
    lda     oamBuffer - 16,y        ; $9DC5  lower the top pair's sprites
    cmp     #$F0                    ; $9DC8  (unless hidden)
    bcs     @second                 ; $9DCA
    adc     temp0                   ; $9DCC
    sta     oamBuffer - 16,y        ; $9DCE

@second:
    lda     oamBuffer - 12,y        ; $9DD1
    cmp     #$F0                    ; $9DD4
    bcs     @done                   ; $9DD6
    adc     temp0                   ; $9DD8
    sta     oamBuffer - 12,y        ; $9DDA

@done:
    rts                             ; $9DDD

; ---------------------------------------------------------------------------
; Eye_Draw
;
; Draw an Eye: a pair of sprites facing its objFacing, sramEnemyTiles
; entry $0A (its eye a slit) while it flies, $08 (wide open) while it is
; stopped (its timer not 0 or $80).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Eye_Draw:
    lda     timerFast+TIMER_ENEMY,x ; $9DDE
    ldx     #$0A                    ; $9DE1  entry $0A,
    asl     a                       ; $9DE3
    beq     @draw                   ; $9DE4
    ldx     #$08                    ; $9DE6  or $08 while stopped

@draw:
    jmp     Sprite_DrawEnemyPairKeepX ; $9DE8

; ---------------------------------------------------------------------------
; Leever_Draw
;
; Draw a Leever: a symmetric pair of sprites (the right one mirrored),
; alternating between sramEnemyTiles entries $0C and $0E every 8 frames,
; in palette 3 and behind the background (attribute $23), so that it
; shows only where the background is empty.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Leever_Draw:
    ldx     #$02                    ; $9DEB  as if facing left
    stx     temp2                   ; $9DED
    lda     #$23                    ; $9DEF  palette 3, behind the background
    sta     temp3                   ; $9DF1
    lda     #$0C                    ; $9DF3  entries $0C / $0E
    jsr     Sprite_DrawAnimatedEnemyPair ; $9DF5
    lda     oamBuffer - 2,y         ; $9DF8  mirror the right sprite
    ora     #$40                    ; $9DFB
    sta     oamBuffer - 2,y         ; $9DFD
    rts                             ; $9E00
; (disassembled with tools/disasm.py; not executed in the test movies)

; ---------------------------------------------------------------------------
; Boon_Draw
;
; Draw a Boon: a pair of sprites facing its objFacing, alternating every
